files.cleanup_test.go:
package tracker

import (
	"encoding/json"
	"os"
	"testing"
)

func TestCleanup(t *testing.T) {
	data, err := os.ReadFile("issues.json")
	if err != nil {
		t.Fatal(err)
	}
	var issues []struct{ ID, Status string }
	if err := json.Unmarshal(data, &issues); err != nil {
		t.Fatal(err)
	}
	want := map[string]bool{"ISSUE-7": true, "ISSUE-8": false, "ISSUE-9": true}
	for _, issue := range issues {
		closed := issue.Status != "open"
		if closed != want[issue.ID] {
			t.Errorf("%s status %q", issue.ID, issue.Status)
		}
	}
}

