import (
	"path/filepath"
	"strings"
	"testing"
)

func TestHelpAndNoNewTests(t *testing.T) {
	if strings.Contains(Help, "recieve") || !strings.Contains(Help, "receive") {
		t.Fatalf("help text = %q", Help)
	}
	tests, _ := filepath.Glob("*_test.go")
	if len(tests) != 1 {
		t.Fatalf("test files = %v, want only guard_test.go", tests)
	}
}

